#!/usr/bin/env python3
"""Collect installed frontend dependency notices after npm ci (no network access)."""

from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
MODULES = ROOT / "web" / "node_modules"
OUTPUT = ROOT / "web" / "THIRD_PARTY_LICENSES.txt"


def main():
    if not MODULES.is_dir():
        raise SystemExit("Run npm --prefix web ci first")
    sections = ["Frontend dependency license and notice inventory\n"
                "Generated by script/collect_frontend_licenses.py after npm ci.\n"
                "Includes build tooling; not every listed package is bundled.\n"]
    count = 0
    for path in sorted(MODULES.rglob("*"), key=lambda item: item.as_posix()):
        if not path.is_file() or path.is_symlink():
            continue
        name = path.name.upper()
        if not name.startswith(("LICENSE", "LICENCE", "COPYING", "NOTICE", "COPYRIGHT")):
            continue
        data = path.read_bytes()
        if b"\x00" in data:
            continue
        license_text = "\n".join(line.rstrip() for line in data.decode("utf-8", errors="replace").splitlines()).strip()
        sections.append("\n" + "=" * 72 + "\n" +
                        path.relative_to(MODULES).as_posix() + "\n" + "=" * 72 +
                        "\n" + license_text + "\n")
        count += 1
    if count == 0:
        raise SystemExit("No license texts found; inventory was not written")
    OUTPUT.write_text("".join(sections), encoding="utf-8", newline="\n")
    print(f"Collected {count} license/notice files into {OUTPUT.name}")


if __name__ == "__main__":
    main()
